import unittest
from solution import client_ip


class TestClientIp(unittest.TestCase):
    def test_untrusted_peer_cannot_spoof(self):
        self.assertEqual(client_ip('203.0.113.9', {'X-Forwarded-For': '10.0.0.1'}, ['10.0.0.0/8']), '203.0.113.9')

    def test_trusted_proxy_forwards_first_valid_ip(self):
        self.assertEqual(client_ip('10.1.2.3', {'X-Forwarded-For': '198.51.100.7, 10.2.3.4'}, ['10.0.0.0/8']), '198.51.100.7')

    def test_invalid_forwarded_value_falls_back(self):
        self.assertEqual(client_ip('10.1.2.3', {'X-Forwarded-For': 'not-an-ip'}, ['10.0.0.0/8']), '10.1.2.3')


if __name__ == '__main__':
    unittest.main()
